pm.variables.set('expect', '{"status": 201, "schema": "Empresa"}');
// CNPJ sintético com dígitos verificadores válidos.
const digits = Array.from({ length: 8 }, () => Math.floor(Math.random() * 10)).join('') + '0001';
const dv = (base, factors) => {
  const sum = base.split('').reduce((acc, d, i) => acc + Number(d) * factors[i], 0) % 11;
  return sum < 2 ? 0 : 11 - sum;
};
const first = dv(digits, [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]);
const second = dv(digits + first, [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]);
pm.collectionVariables.set('tempCnpj', `${digits}${first}${second}`);

